// Lote del scraper: { documents: [{ code, title, sourceUrl, capturedAt, isFictional, status, text }] }
// Sale un item por fragmento. El texto es DATO NO CONFIABLE: no se interpreta, solo se limpia y trocea.
const body = $input.first().json.body || {};
const documents = Array.isArray(body.documents) ? body.documents : [];

const CHUNK_CHARS = 900;   // ~250 tokens: entra cómodo en el contexto del chat
const OVERLAP_CHARS = 150; // solapamiento para no cortar un requisito a la mitad

const clean = (t) =>
  String(t || '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const split = (text) => {
  const chunks = [];
  let current = '';
  for (const paragraph of text.split(/\n{2,}/)) {
    const candidate = current ? `${current}\n\n${paragraph}` : paragraph;
    if (candidate.length > CHUNK_CHARS && current) {
      chunks.push(current);
      current = `${current.slice(-OVERLAP_CHARS)}\n\n${paragraph}`;
    } else {
      current = candidate;
    }
    // Párrafos gigantes (páginas sin saltos): corte duro con solapamiento
    while (current.length > CHUNK_CHARS * 1.5) {
      chunks.push(current.slice(0, CHUNK_CHARS));
      current = current.slice(CHUNK_CHARS - OVERLAP_CHARS);
    }
  }
  if (current.trim()) chunks.push(current);
  return chunks;
};

const out = [];
for (const d of documents) {
  const text = clean(d.text);
  if (!d.code || !d.title || text.length < 40) continue;
  split(text).forEach((chunk, index) => {
    out.push({
      json: {
        code: d.code,
        title: d.title,
        sourceUrl: d.sourceUrl || '',
        capturedAt: d.capturedAt || new Date().toISOString().slice(0, 10),
        isFictional: d.isFictional === true,
        // Lo scrapeado entra pendiente de revisión; solo lo curado a mano puede venir aprobado
        status: d.status === 'approved' ? 'approved' : 'pending_review',
        index,
        // El título en cada fragmento mejora la búsqueda ("¿cuánto dura Mecatrónica?")
        text: `${d.title}\n\n${chunk.trim()}`,
      },
    });
  });
}

if (out.length === 0) throw new Error('El lote no trae texto para indexar');
return out;

// Junta cada fragmento con su embedding y arma el lote para el backend
const chunks = $('Validar y trocear').all();
const embeddings = $input.all();
const byCode = new Map();

chunks.forEach((item, i) => {
  const c = item.json;
  const embedding = embeddings[i]?.json?.embeddings?.[0];
  if (!Array.isArray(embedding)) throw new Error(`Sin embedding para ${c.code} #${c.index}`);
  if (!byCode.has(c.code)) {
    byCode.set(c.code, {
      code: c.code,
      title: c.title,
      sourceUrl: c.sourceUrl,
      capturedAt: c.capturedAt,
      isFictional: c.isFictional,
      status: c.status,
      chunks: [],
    });
  }
  byCode.get(c.code).chunks.push({ text: c.text, embedding });
});

return [{ json: { documents: [...byCode.values()] } }];
